import React from 'react'
import styled from 'styled-components'
import VideoControls from 'components/shared/Sessions/Video/VideoControls'
import ScreenVisitItemHeader from './ScreenVisitItemHeader'

const FallbackContainer = styled.div`
    display: flex;
    flex-direction: column;
    flex-grow: 1;
`

const FallbackInner = styled.div`
    flex-grow: 1;
    position: relative;
`

// Render session detials from session list if available
const FallBackHeaderWrapper = ({ sessionListItem, children }) => {
  const videoRef = React.useRef()
  const Fallback = React.useMemo(() => {
    if (sessionListItem) {
      return (
        <FallbackContainer>
          <ScreenVisitItemHeader
            session={sessionListItem}
          />
          <FallbackInner>
            <div />
          </FallbackInner>
          <VideoControls
            screens={[]}
            videoRef={videoRef}
          />
        </FallbackContainer>
      )
    }
    return null
  }, [sessionListItem])

  return (
    <React.Suspense fallback={Fallback}>
      {children}
    </React.Suspense>
  )

}

export default React.memo(FallBackHeaderWrapper)