/* eslint-disable camelcase */
import React, { memo, useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import { Tooltip, Badge } from 'antd';
import { useSelector } from 'react-redux';

import { getUtcDate } from 'Utils/DateConversion/dateConversionUtils';
import LinkHeaderAttribute from 'components/common/LinkHeaderAttribute';
import { useSessionHeader, useSessionTimeLine } from 'components/shared/Sessions/Context';
import CrashSvg from 'public/static/session-replay/app-crashes.svg';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';

// new session replay icons
import UserIcon from 'public/static/session-replay/user.svg';
import LocationIcon from 'public/static/session-replay/location.svg';
import CalendarIcon from 'public/static/session-replay/calendar.svg';
import LabelsIcon from 'public/static/session-replay/label.svg';

import SessionCustomLabels from 'components/shared/Sessions/Video/Header/SessionCustomLabels';

import { getNewSessionData } from 'Utils/helpers/SessionUtils';
import aiSessionListRedirectionHelper from 'Utils/helpers/aiSessionListRedirectionHelper';
import { useUserName } from 'hooks/useUserName';
import {
  HeaderWrap,
  Header,
  HeaderItem,
  ScreenNameStyled,
  CrashedButton,
  UserNameContainer,
  LabelContainer,
  LabelWrapper,
} from './styles';

const SessionVisitItemHeader = ({ session }) => {
  const {
    appFilter,
    urlReducer: urlQuery,
  } = useSelector((state) => state);
  const { parentType, appId } = urlQuery;
  const sessionSegment = appFilter?.heatmap?.segment;
  const dateSegment =  appFilter?.dateSegment;

  const isWebHeatmaps = useMemo(() => parentType === 'webHeatmaps', [parentType]);

  const { sessionDetail } = useSessionTimeLine();
  const { setSelectedHeaderField } = useSessionHeader();
  const { isCrashedLog } = sessionDetail || {};

  const [labelSession, setLabelSession] = useState([]);
  const [showCustomLabel, setShowCustomLabel] = useState(false);

  const sessionDetails = useMemo(
    () => getNewSessionData(session, parentType),
    [session, parentType]
  );

  const sessionLabel = sessionDetails?.customLabel;

  useEffect(() => {
    if (sessionLabel) {
      setLabelSession(sessionLabel);
    }
  }, [sessionLabel])

  const { city, country, sessionid, sessionNumber, uxcamuserid ,kUXCam_UserIdentity, deviceLocalDateTime} = sessionDetails || {};

  const getSessionHref = useMemo(() => ({
      pathname: '/integration',
      query: {
        parentType: 'aiSessionsList',
        appId,
        sessionpage: 1,
        sessionid
      },
    }), [appId, sessionid])
  
  const getUserHref = useMemo(() => ({
      pathname: '/integration',
      query: {
        appId,
        parentType: 'usersList',
        uxcamuserid,
        sessionPage: 1,
        userpage: 1,
      },
  }), [appId, uxcamuserid])
  
  const userNameConfig = useUserName(
    {
      customUserId: kUXCam_UserIdentity,
      uxcamuserid,
    },
    ScreenNameStyled
  );

  const UserName = useMemo(
    () => (
      <UserNameContainer>
        {
          !isWebHeatmaps && (
            <>
              <Link
                passHref
                href={getSessionHref}
                as={urlSegmentEncoder( aiSessionListRedirectionHelper.modifyUrl( `/app/${appId}/sessions/list/1/${sessionid}` ), [dateSegment])}
                legacyBehavior
              >
                <a href="#!" target="_blank" rel="noreferrer">
                  <ScreenNameStyled>{`Session ${sessionNumber}  `}</ScreenNameStyled>
                </a>
              </Link>
              of
            </>
          )
        }
        <Link
          href={getUserHref}
          as={urlSegmentEncoder(`/app/${appId}/users/list/1/${uxcamuserid}`, [dateSegment])}
          passHref
          legacyBehavior
        >
          <a href="#!" target="_blank" rel="noreferrer">
            {userNameConfig}
          </a>
        </Link>
      </UserNameContainer>
    ),
    [appId, dateSegment, getSessionHref, getUserHref, isWebHeatmaps, parentType, sessionNumber, sessionid, userNameConfig, uxcamuserid]
  );

  const LocationHeaderItem = useMemo(() => {
    const attribute = city === 'N/A' ? 'device_country' : 'device_city';
    const value =
      city === 'N/A'
        ? country
        : city;

    const locationTooltip = `Location is ${city === 'N/A' ? 'Undetermined city' : city
      }, ${country || 'N/A'}`;

    return (
      <HeaderItem>
        <LocationIcon />{' '}
        <LinkHeaderAttribute
          segment={sessionSegment}
          _attribute={attribute}
          __value={value}
          tooltipTitle_value={locationTooltip}
          _operator="in"
          table='session'
        >
          {city || 'Undetermined City'}, {country || 'N/A'}
        </LinkHeaderAttribute>
      </HeaderItem>
    );
  }, [city, country, sessionSegment]);

  const DateHeaderItem = useMemo(() => {
    const dateTimeObj = deviceLocalDateTime;

    const dateTimeDashFormat =
      dateTimeObj && getUtcDate(dateTimeObj, 'yyyy-MM-dd');
    const dateTimeSlashFormat =
      dateTimeObj && getUtcDate(dateTimeObj, 'dd-MMMM-yyyy');
    const displayDateTimeSlashFormat =
      dateTimeObj && getUtcDate(dateTimeObj, 'MMM d, yyyy');
    const dateDayTime = dateTimeObj && getUtcDate(dateTimeObj, 'EEEE hh:mm a');

    return (
      <HeaderItem>
        <CalendarIcon />
        <LinkHeaderAttribute
          segment={sessionSegment}
          _attribute="session_recordedon"
          __value={dateTimeDashFormat}
          _operator="on"
          _isNotArrayFormat
          tooltipTitle_value={`Device time is ${dateDayTime}, ${dateTimeSlashFormat}`}
          table='session'
        >
          {displayDateTimeSlashFormat}
        </LinkHeaderAttribute>
      </HeaderItem>
    );
  }, [deviceLocalDateTime, sessionSegment]);

  return (
    <>
      <HeaderWrap>
        <Header>
          <HeaderItem>
            <UserIcon />
            {UserName}
          </HeaderItem>
          {LocationHeaderItem}
          {DateHeaderItem}
          <HeaderItem data-intercom-target="Session Label">
            <span
              aria-hidden="true"
              onClick={() => setShowCustomLabel(!showCustomLabel)}
              className="labels-nav"
            >
              <Tooltip
                overlayClassName="session-label-tooltip"
                title="Session Labels"
                placement="bottom"
              >
                <LabelContainer>
                  <LabelsIcon />
                  Labels 
                  <Badge count={labelSession?.length || 0} />
                </LabelContainer>
              </Tooltip>
            </span>
          </HeaderItem>
          {isCrashedLog ? <CrashedButton onClick={() => setSelectedHeaderField('crash')}><CrashSvg />Crashed</CrashedButton> : null}
        </Header>
      </HeaderWrap>
      {showCustomLabel && (
          <SessionCustomLabels
            className="session-label-expand"
            setShowCustomLabel={setShowCustomLabel}
          />
      )}
    </>
  );
};

export default memo(SessionVisitItemHeader);