import React, { memo, useEffect, useMemo, useRef } from 'react';
import styled from 'styled-components';
import { useSessionHeader, useSessionTimeLine, useSessionVideoContext, useSessionVideoControlls } from 'components/shared/Sessions/Context';
import { useSessionDetail } from 'components/features/sessions/hooks/useSessionDetail';
import SessionVideo from 'components/shared/Sessions/Video';
import { useDispatch, useSelector } from 'react-redux';
import { trackPageViews } from 'redux/actions/trackingReport';
import StackTrace from 'components/shared/Sessions/Video/Header/StackTrace';
import ScreenVisitItemHeader from './ScreenVisitItemHeader';
import FallBackHeaderWrapper from './FallBackHeaderWrapper';

const Container = styled.div`
  display: flex;
  flex-direction: column;
  flex-grow: 1;
  max-width: 100%;
  background: #fff;
  height: calc(100vh - 180px);

  .loader.center-loader {
    right: 34%;
  }

  .stack-trace-box {
    height: calc(100vh - 270px);
    .ant-collapse {
      height: calc(100vh - 365px) !important;
    }
  }
`;
const ErrorMessage = styled.div`
  padding: 20px !important;
  border: 1px solid rgba(37, 56, 88, 0.2);
  border-radius: 4px;
  width: 315px;
  max-width: 100%;
  text-align: left;
`;
const ErrorContainer = styled.div`
  &[aria-hidden='true'] {
    display: none;
  }
  border-radius: 0;
  display: flex;
  text-align: center;
  align-items: center;
  justify-content: center;
  flex-grow: 1;
`;

const CrashWrapper = styled.div`
.ant-collapse {
  height: calc(100vh - 355px) !important;
}
`

const ScreenSessionDetails = memo(
  ({ sessionId, appId, toggleFullScreen, uploadedOn, multiScreenSkippedData }) => {

    const mounted = useRef(false);
    const dispatch = useDispatch();

    const { screenname, sessionid } = useSelector(state => state.urlReducer);
    // const starttimeCopy = Number(starttime)
    const {
      setSessionDetail,
      sessionDetail,      
    } = useSessionTimeLine();

    const { selectedHeaderField } = useSessionHeader();

    const { videoElemRef } = useSessionVideoControlls();
    const { userPausedVideo: isVideoPaused } = useSessionVideoContext();
    const isVideoEnded = useMemo(() => videoElemRef?.current?.ended, [videoElemRef?.current?.ended]);

    // const { time } = currentScreen || {};

    const reqBody = useMemo(
      () => ({
        appid: appId,
        sessionid: sessionId,
        uploadedon: uploadedOn
      }),
      [appId, sessionId, uploadedOn]
    );

    const queryKey = useMemo(() => sessionId, [sessionId]);

    const { data } = useSessionDetail(queryKey, reqBody)

    // const foundScreen = useMemo(() => data?.screenTimeline?.activities[screenNumber], [screenNumber, data?.screenTimeline?.activities]);

    const respSessionId = data?.['_id'];


    useEffect(() => {
      mounted.current = true;
      return () => {
        mounted.current = false;
      };
    }, []);

    useEffect(() => {
      (isVideoPaused || isVideoEnded) &&
        dispatch(trackPageViews(null, {
          eventName: 'hm_session_replay_stopped',
          track_type: 'event',
          eventProperty: {
            screenname,
            sessionid
          }
        }))
    }, [dispatch, isVideoPaused, isVideoEnded, screenname, sessionid]);

    // useEffect(() => {
    //   if (isVideoPlaying) setUserPausedVideo(false);
    // }, [isVideoPlaying, setUserPausedVideo])

    // useEffect(() => {
    //   if (mounted.current) {
    //     const { endTime } = foundScreen || {}; // endTime -> screen end time
    //     if (typeof endTime === 'undefined') return
    //     if (time === endTime) {
    //       setUserPausedVideo(true);
    //       videoElemRef?.current?.pause();
    //     }
    //   }
    // }, [time, videoElemRef, setUserPausedVideo, foundScreen]);

    useEffect(() => {
      if (data) setSessionDetail(data);
    }, [sessionId, data, setSessionDetail]);

    // const resumeVideo = () => {
    //   setUserPausedVideo(false);
    //   videoElemRef?.current?.play();
    // }

    // const replayVideo = useCallback(() => {
    //   setUserPausedVideo(false);
    //   videoElemRef.current.currentTime = starttimeCopy;
    //   videoElemRef.current.play();
    // }, [setUserPausedVideo, starttimeCopy, videoElemRef])

    return (
      <>
        {(!sessionDetail?.error?.message && respSessionId) ? (
          <>
            <ScreenVisitItemHeader appId={appId} session={data} />
            {selectedHeaderField === 'sessionVideo' ?
              <>
                {/* <ScreenReplayOverlay
                  isVideoEnded={isVideoEnded}
                  isVideoPaused={isVideoPaused}
                  resumeVideo={resumeVideo}
                  replayVideo={replayVideo} /> */}
                <SessionVideo
                  className='session-video-modal'
                  appId={appId}
                  session={data}
                  key={respSessionId}
                  toggleFullScreen={toggleFullScreen}
                  multiScreenSkippedData={multiScreenSkippedData}
                  // blurBackground={isVideoEnded || isVideoPaused}
                /></> : null}
            {selectedHeaderField?.includes('crash') ? <CrashWrapper> <StackTrace /> </CrashWrapper> : null}
          </>
        ) : (
          <ErrorContainer>
            <ErrorMessage>
              <p>{sessionDetail?.error?.message || 'Something went wrong'}</p>
            </ErrorMessage>
          </ErrorContainer>
        )
        }
      </>
    );
  }
);

const SessionReplayWrapper = ({
  sessionId,
  appId,
  sessionList,
  userId,
  uploadedOn,
  toggleFullScreen,
  multiScreenSkippedData,
}) => {
  const sessionListItem = useMemo(
    () =>
      sessionList &&
      sessionList.body.find(({ sessionid }) => sessionid === sessionId),
    [sessionList, sessionId]
  );

  return (
    <Container>
      <FallBackHeaderWrapper
        sessionListItem={sessionListItem}
        toggleFullScreen={toggleFullScreen}
        appId={appId}
      >
        <ScreenSessionDetails
          toggleFullScreen={toggleFullScreen}
          sessionId={sessionId}
          appId={appId}
          userId={userId}
          uploadedOn={uploadedOn}
          multiScreenSkippedData={multiScreenSkippedData}
        />
      </FallBackHeaderWrapper>
    </Container>
  );
};

export default memo(SessionReplayWrapper);
